from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused

STOCK_OPS = journal.OPS


def is_op(e: dict) -> bool:
    return e.get("op") in STOCK_OPS


def _broken(msg: str):
    return DataError("journal", msg)


def read_stacks(entries: list[dict]):
    """Returns (done, undone, dropped) as lists of operation lines.

    dropped is a set of seqs.  Raises DataError(journal) if undo/redo lines
    do not match the stacks.
    """
    done: list[dict] = []
    undone: list[dict] = []
    dropped: set[int] = set()
    for e in entries:
        op = e.get("op")
        if op in STOCK_OPS:
            for u in undone:
                dropped.add(u["seq"])
            undone = []
            done.append(e)
        elif op == "undo":
            if not done or done[-1]["seq"] != e.get("target") or isinstance(e.get("target"), bool):
                raise _broken(f"undo #{e['seq']} does not match the stack")
            undone.append(done.pop())
        elif op == "redo":
            if not undone or undone[-1]["seq"] != e.get("target") or isinstance(e.get("target"), bool):
                raise _broken(f"redo #{e['seq']} does not match the stack")
            done.append(undone.pop())
    return done, undone, dropped


def _qty(value) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or value < 0:
        raise _broken("bad quantity in journal")
    return value


def _effects(e: dict) -> list[tuple[str, int]]:
    """(bin, before) of each effect of a format 2 line."""
    effs = e.get("effects")
    if not isinstance(effs, list):
        raise _broken(f"#{e['seq']}: no effects")
    out = []
    for x in effs:
        if not isinstance(x, dict) or not isinstance(x.get("bin"), str):
            raise _broken(f"#{e['seq']}: bad effect")
        out.append((normalize(x["bin"]), _qty(x.get("before"))))
    return out


def _v1_bin(e: dict, key: str) -> str:
    if not isinstance(e.get(key), str):
        raise _broken(f"#{e['seq']}: no {key}")
    return normalize(e[key])


def _v1_changes(ctx, e: dict) -> list[tuple[str, int]]:
    """Changes (bin, delta) that taking back a format 1 line makes, in order."""
    op = e["op"]
    if op == "receive":
        qty = _qty(e.get("qty"))
        if e.get("uom") == "pk":
            item = ctx.items.get(e.get("sku"))
            if item is None:
                raise Refused("unknown-sku", f"no item {e.get('sku')}")
            qty *= item.pack_size
        return [(_v1_bin(e, "bin"), -qty)]
    if op == "issue":
        picks = e.get("picks")
        if not isinstance(picks, list):
            raise _broken(f"#{e['seq']}: no picks")
        out = []
        for p in reversed(picks):
            if not isinstance(p, (list, tuple)) or len(p) != 2 or not isinstance(p[0], str):
                raise _broken(f"#{e['seq']}: bad pick")
            out.append((normalize(p[0]), _qty(p[1])))
        return out
    if op == "move":
        qty = _qty(e.get("qty"))
        return [(_v1_bin(e, "to"), -qty), (_v1_bin(e, "from"), qty)]
    raise _broken(f"#{e['seq']}: cannot undo")


def _apply(ctx, store, sku: str, targets: list) -> list[dict]:
    """targets: (bin, qty or None, delta). Sets bins without the retired-bin rule."""
    for code, _, _ in targets:
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")
    effects = []
    for code, qty, delta in targets:
        before = store.qty(sku, code)
        after = qty if qty is not None else before + delta
        if after < 0:
            raise _broken(f"{sku} in {code} would go below zero")
        store.restore(sku, code, after)
        effects.append({"bin": code, "before": before, "after": after})
    return effects


def run_steps(ctx, kind: str, steps: int):
    """Carries out undo or redo steps; returns (store, new entries)."""
    entries = list(ctx.entries)
    done, undone, _ = read_stacks(entries)
    store = ctx.store.copy()
    new = []
    for _ in range(steps):
        if kind == "undo":
            if not done:
                raise Refused("nothing-to-undo", "nothing to undo")
            op = done[-1]
