        new.append((line, op))
        if kind == "undo":
            undone.append(done.pop())
        else:
            done.append(undone.pop())
    return store, new


def history(entries: list[dict], limit: int) -> list[tuple[dict, str]]:
    done, undone, dropped = read_stacks(entries)
    on_done = {e["seq"] for e in done}
    on_undone = {e["seq"] for e in undone}
    ops = [e for e in entries if is_op(e)]
    out = []
    for e in reversed(ops[-limit:]):
        if e["seq"] in on_undone:
            status = "undone"
        elif e["seq"] in on_done:
            status = "barrier" if e["op"] == "fix" else "done"
        else:
            status = "dropped"
        out.append((e, status))
    return out
